import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties,
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights
    ) public {
        vm.assume(_nft != address(0));
        vm.assume(_feeRate <= 5_000);
        vm.assume(_virtualNftReserves > 0);
