        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        bool sellDoesNotRevert;
        try c.sell(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0)), new IStolenNftOracle.Message[](0)) {
