pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate, uint8 _decimals, uint128 _virtualBase, uint128 _virtualNft, uint56 _changeFee, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Bound feeRate to a range that certainly includes values above 5_000
        _feeRate = uint16(bound(_feeRate, 5001, type(uint16).max));
        // Keep decimals reasonable to avoid overflow in unrelated code, but wide enough
        _decimals = uint8(bound(_decimals, 0, 36));
        // Setup addresses: base token and nft can be any non-zero addresses
        address baseToken = makeAddr("baseToken");
        address nftAddr = makeAddr("nft");
        // Deploy minimal ERC20 mock that returns the fuzzed decimals
        MockERC20 mockBase = new MockERC20(_decimals);
        // If baseToken is address(0) (ETH), the revert condition still depends on feeRate > 5000.
        // We test with a non-zero base token to avoid complications with ETH handling.
        // The initialization code path for the check is the same regardless of baseToken.
        bool ok;
        try c.initialize(
            address(mockBase),
            nftAddr,
            _virtualBase,
            _virtualNft,
            _changeFee,
            _feeRate,
            bytes32(0),
            _useStolenNftOracle,
            _payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference C must revert for feeRate > 5000; mutant must not revert for some feeRate > 5000.
        // The assertion checks that the initialization reverts (ok == false).
        // The fuzzer will find that the mutant succeeds (ok == true) for some input, violating the property.
        assertTrue(!ok, "Initialization should revert for feeRate > 5000");
    }
}

contract MockERC20 {
    uint8 public decimals;
    constructor(uint8 _decimals) {
        decimals = _decimals;
    }
}

