pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        bool refReverted;
        bool mutReverted;

        // Call initialize on reference C (P) via try/catch
        try c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            refReverted = false;
        } catch {
            refReverted = true;
        }

        // Call initialize on mutant C (M) – same bytecode but we simulate the mutant by checking the assertion logic
        // Since we cannot have both versions in the same test contract, we assert the property:
        // Reference reverts only when _feeRate > 5000; mutant reverts when _feeRate > 0.
        // We check the actual behavior of the deployed contract (which is the reference in this test).
        // The test will pass for the reference and fail when the mutant is substituted.

        bool shouldRevert = _feeRate > 5000;
        assertTrue(refReverted == shouldRevert);
    }
}

